#define PI 3.14159265359

#define TILES 0.9
#define SPEED 10.0
#define DIRECTION 0.4
#define WARP_SCALE 0.0
#define WARP_TILING 10.0
#define COLOR1 vec3(0.165,0.753,0.235) // 默认红色
#define COLOR2 vec3(0.745,0.212,0.153) // 默认蓝色

vec2 rotatePoint(vec2 pt, vec2 center, float angle) {
    float sinAngle = sin(angle);
    float cosAngle = cos(angle);
    pt -= center;
    vec2 r = vec2(1.0);
    r.x = pt.x * cosAngle - pt.y * sinAngle;
    r.y = pt.x * sinAngle + pt.y * cosAngle;
    r += center;
    return r;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord ){
    vec2 uv = fragCoord/iResolution.xy;

    vec2 uv2 = rotatePoint(uv.xy, vec2(0.5, 0.5), DIRECTION * 2.0 * PI);

    uv2.x += sin(uv2.y * WARP_TILING * PI * 2.0) * WARP_SCALE + SPEED;
    uv2.x *= TILES * iTime /8.;

    float st = floor(fract(uv2.x) + 0.5);

    vec3 color = mix(COLOR1, COLOR2, st);
    // 这里可以添加输出颜色的代码，例如：
    fragColor = vec4(color, 1.0);
}
